/// 3·a + 5·b + 7·c = n, following the canonical rules:
///   • if n % 3 == 0:    [n/3, 0, 0]
///   • if n % 3 == 1:
///       – if n < 7:     [-1]
///       – else:         [(n-7)/3, 0, 1]
